package main

import (
	"context"
	"encoding/json"
	"fmt"
	"net"
	"net/http"
	"net/url"
	"time"

	"github.com/gofiber/fiber/v2"
)

// webhookRequest represents the expected JSON request body
type webhookRequest struct {
	WebhookURL string `json:"webhook_url"`
}

// ConfigureWebhook handles POST requests to configure a webhook URL.
// It validates the URL, sends a test GET request to it (with SSRF prevention),
// and saves the configuration.
func ConfigureWebhook(ctx *fiber.Ctx) error {
	// Parse the JSON request body
	var req webhookRequest
	if err := ctx.BodyParser(&req); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid JSON format",
		})
	}

	// Validate that webhook_url is provided
	if req.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook_url is required",
		})
	}

	// Validate URL format
	parsedURL, err := url.Parse(req.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid webhook URL format",
		})
	}

	// Ensure the URL has an HTTP/HTTPS scheme
	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook URL must use http or https scheme",
		})
	}

	// Extract host (with port if present)
	host := parsedURL.Hostname()
	if host == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook URL contains an empty host",
		})
	}

	// Prevent Server-Side Request Forgery (SSRF): resolve the host and
	// ensure none of the IP addresses are private, loopback, or otherwise unsafe.
	ips, err := net.LookupIP(host)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   fmt.Sprintf("Unable to resolve webhook URL host: %v", err),
		})
	}

	for _, ip := range ips {
		if isUnsafeIP(ip) {
			return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
				"success": false,
				"error":   "webhook URL points to an internal or restricted network address",
			})
		}
	}

	// Create a custom HTTP client with:
	// - a timeout
	// - disabled redirects (to prevent SSRF bypass via redirects)
	client := &http.Client{
		Timeout: 3 * time.Second,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			return http.ErrUseLastResponse
		},
		Transport: &http.Transport{
			DialContext: (&net.Dialer{
				Timeout:   3 * time.Second,
				KeepAlive: 3 * time.Second,
			}).DialContext,
		},
	}

	// Send a test GET request to the webhook URL
	resp, err := client.Get(req.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   fmt.Sprintf("Failed to send test request to webhook URL: %v", err),
		})
	}
	defer resp.Body.Close()

	// The webhook should respond with a 2xx status code
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   fmt.Sprintf("Webhook URL returned non-success status: %d", resp.StatusCode),
		})
	}

	// Save the configuration (implementation assumed)
	// db.SaveWebhookURL(req.WebhookURL)

	return ctx.Status(fiber.StatusOK).JSON(fiber.Map{
		"success": true,
		"message": "Webhook configured successfully",
	})
}

// isUnsafeIP checks whether an IP address is loopback, private, link-local,
// unspecified, or otherwise not suitable for external requests.
func isUnsafeIP(ip net.IP) bool {
	// IPv4 or IPv6
	if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() ||
		ip.IsLinkLocalMulticast() || ip.IsUnspecified() {
		return true
	}

	// Additional checks for special ranges (e.g., 0.0.0.0/8, 127.0.0.0/8 already covered)
	// For IPv4 we can also check IsGlobalUnicast, but that excludes some safe IPs.
	// Just catch the clearly unsafe ones.
	if ip4 := ip.To4(); ip4 != nil {
		// Check for 0.0.0.0/8 (unspecified) already handled.
		// Check for broadcast 255.255.255.255
		if ip4.Equal(net.IPv4bcast) {
			return true
		}
	}

	// For IPv6, you might want to block site-local (fec0::/10) deprecated, but still.
	// ip.IsPrivate() covers IPv6 site-local (fec0::/10) and unique local (fc00::/7).
	return false
}

