package main

import (
    "net/http"
    "time"

    "github.com/gofiber/fiber/v2"
)

// in-memory storage for the configured webhook URL
var webhookURL string

func main() {
    app := fiber.New()

    app.Post("/configure-webhook", ConfigureWebhook)

    app.Listen(":3000")
}

// ConfigureWebhook receives a POST request with a JSON body containing "webhook_url".
// It validates the URL by sending a GET request with a 3-second timeout and saves the configuration.
func ConfigureWebhook(ctx *fiber.Ctx) error {
    var body struct {
        WebhookURL string `json:"webhook_url"`
    }

    if err := ctx.BodyParser(&body); err != nil {
        return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
            "error": "Invalid request body",
        })
    }

    if body.WebhookURL == "" {
        return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
            "error": "webhook_url is required",
        })
    }

    // validate the webhook URL with a test GET request
    client := &http.Client{
        Timeout: 3 * time.Second,
    }

    req, err := http.NewRequest("GET", body.WebhookURL, nil)
    if err != nil {
        return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
            "error": "Invalid URL format",
        })
    }

    resp, err := client.Do(req)
    if err != nil {
        return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
            "error": "Failed to reach webhook URL: " + err.Error(),
        })
    }
    defer resp.Body.Close()

    if resp.StatusCode < 200 || resp.StatusCode >= 300 {
        return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
            "error": "Webhook URL responded with non-success status code",
        })
    }

    // save the configuration (in-memory)
    webhookURL = body.WebhookURL

    return ctx.JSON(fiber.Map{
        "message":     "Webhook URL configured successfully",
        "webhook_url": body.WebhookURL,
    })
}

