			"success": false,
			"error":   fmt.Sprintf("Failed to send test request: %v", err),
		})
	}
	defer resp.Body.Close()

	// Check for a successful status (2xx)
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   fmt.Sprintf("Webhook URL returned status %d", resp.StatusCode),
		})
	}

