package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"time"

	"github.com/gofiber/fiber/v2"
)

// Global variable to store the validated webhook URL (simple in-memory store)
var savedWebhookURL string

// Request body structure
type configureRequest struct {
	WebhookURL string `json:"webhook_url"`
}

// Response structure
type configureResponse struct {
	Status     string `json:"status"`
	Message    string `json:"message,omitempty"`
	WebhookURL string `json:"webhook_url,omitempty"`
}

func main() {
	app := fiber.New()

	// Register route
	app.Post("/configure-webhook", ConfigureWebhook)

	log.Fatal(app.Listen(":3000"))
}

// ConfigureWebhook handles POST requests to configure a webhook.
// It validates the provided webhook URL by sending a GET request with a 3-second timeout,
// then saves the configuration and returns a JSON response.
func ConfigureWebhook(ctx *fiber.Ctx) error {
	var req configureRequest

	// Parse JSON body
	if err := json.Unmarshal(ctx.Body(), &req); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(configureResponse{
			Status:  "error",
			Message: "Invalid JSON body",
		})
	}

	// Validate that webhook_url is present and not empty
	if req.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(configureResponse{
			Status:  "error",
			Message: "webhook_url is required",
		})
	}

	// Create HTTP client with 3-second timeout
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	// Send test GET request
	resp, err := client.Get(req.WebhookURL)
	if err != nil {
		// This includes timeout errors, DNS errors, connection refused, etc.
		return ctx.Status(fiber.StatusBadRequest).JSON(configureResponse{
			Status:  "error",
			Message: fmt.Sprintf("Failed to reach webhook URL: %v", err),
		})
	}
	// Important: close the response body to avoid resource leak
	if resp != nil {
		resp.Body.Close()
	}

	// Save configuration (simple in-memory store)
	savedWebhookURL = req.WebhookURL

	// Return success response
	return ctx.Status(fiber.StatusOK).JSON(configureResponse{
		Status:     "success",
		Message:    "Webhook configured successfully",
		WebhookURL: savedWebhookURL,
	})
}

