package main

import (
	"context"
	"encoding/json"
	"net/http"
	"time"

	"github.com/gofiber/fiber/v2"
)

// In-memory store for the webhook URL
var webhookConfigURL string

func main() {
	app := fiber.New()

	app.Post("/configure-webhook", ConfigureWebhook)

	if err := app.Listen(":3000"); err != nil {
		panic(err)
	}
}

// ConfigureWebhook handles the configuration of a webhook URL.
func ConfigureWebhook(ctx *fiber.Ctx) error {
	// Parse the request body
	type requestBody struct {
		WebhookURL string `json:"webhook_url"`
	}
	var body requestBody
	if err := ctx.BodyParser(&body); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"message": "Invalid request body",
		})
	}

	if body.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"message": "webhook_url is required",
		})
	}

	// Validate the webhook URL by sending a test GET request with a 3-second timeout
	if err := validateWebhookURL(body.WebhookURL); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"message": "Webhook validation failed: " + err.Error(),
		})
	}

	// Save the webhook URL
	webhookConfigURL = body.WebhookURL

	return ctx.JSON(fiber.Map{
		"success": true,
		"message": "Webhook configured successfully",
	})
}

// validateWebhookURL sends a GET request to the given URL with a 3-second timeout
// and returns an error if the request fails or the status is not 2xx.
func validateWebhookURL(url string) error {
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	req, err := http.NewRequestWithContext(context.Background(), http.MethodGet, url, nil)
	if err != nil {
		return err
	}

	resp, err := client.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()

	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return http.ErrNotSupported // or a custom error
	}

	return nil
}

