// isPublicHost checks if the given host is a public IP and not a reserved/internal address.
// It resolves the host to IP addresses and verifies that none are internal/loopback/etc.
func isPublicHost(host string) (bool, error) {
	// Check if host is an IP literal without a port
	if ip := net.ParseIP(host); ip != nil {
		return isPublicIP(ip), nil
	}
	// Resolve host to IP addresses
	ips, err := net.LookupIP(host)
	if err != nil {
		return false, err
	}
	if len(ips) == 0 {
		return false, fmt.Errorf("no IPs resolved for host")
	}
	for _, ip := range ips {
		if !isPublicIP(ip) {
			return false, nil
		}
	}
	return true, nil
}

// isPublicIP checks if an IP is not reserved, loopback, private, link-local, or unspecified.
func isPublicIP(ip net.IP) bool {
	if ip == nil {
		return false
	}
	// Treat IPv4-mapped IPv6 addresses as IPv4
	if ip4 := ip.To4(); ip4 != nil {
		ip = ip4
	}
	if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() || ip.IsUnspecified() {
		return false
	}
	// Check for IPv4 broadcast address
	if ip.Equal(net.IPv4bcast) {
		return false
	}
	// For pure IPv6 addresses, reject multicast
	if ip.To16() != nil && ip.To4() == nil {
		if ip.IsMulticast() {
			return false
		}
	}
	return true
}

// ConfigureWebhook handles POST requests to configure a webhook URL.
// It validates the URL by sending a test GET request and prevents SSRF attacks.
func ConfigureWebhook(ctx *fiber.Ctx) error {
	// Parse the JSON request body
	var req webhookRequest
	if err := ctx.BodyParser(&req); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid JSON format",
		})
	}

	// Validate that webhook_url is provided
	if req.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook_url is required",
		})
	}

	// Limit URL length to prevent abuse
	if len(req.WebhookURL) > 2048 {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook_url is too long",
		})
	}

	// Validate URL format and scheme
	parsedURL, err := url.ParseRequestURI(req.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid webhook URL format",
		})
	}

	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook URL must use http or https scheme",
		})
	}

	// Extract host to check for internal/reserved addresses (SSRF prevention)
	host := parsedURL.Hostname()
	if host == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid webhook URL: missing host",
		})
	}

	public, err := isPublicHost(host)
	if err != nil || !public {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Webhook URL points to an internal or reserved address",
		})
	}

	// Create a custom HTTP client with timeout and disabled redirects
	// Disabling redirects prevents bypassing SSRF checks via redirection
	client := &http.Client{
		Timeout: 3 * time.Second,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			return http.ErrUseLastResponse
		},
	}

	// Send a test GET request to the webhook URL (as per requirement)
	resp, err := client.Get(req.WebhookURL)
	if err != nil {
		// Do not leak internal error details to the client
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Failed to send test request to webhook URL",
		})
	}
	defer resp.Body.Close()

	// Check that the webhook returned a successful (2xx) response
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   fmt.Sprintf("Webhook URL returned non-success status: %d", resp.StatusCode),
		})
	}

	// Save the configuration (implementation specific)
	// db.SaveWebhookURL(req.WebhookURL)

	// Return success response
	return ctx.Status(fiber.StatusOK).JSON(fiber.Map{
		"success": true,
		"message": "Webhook configured successfully",
	})
}

