package main

import (
	"encoding/json"
	"log"
	"net/http"
	"sync"
	"time"

	"github.com/gofiber/fiber/v2"
)

// Global storage for the webhook configuration.
var (
	webhookConfig struct {
		WebhookURL string `json:"webhook_url"`
	}
	mu sync.Mutex
)

// ConfigureWebhook handles POST requests to set a webhook URL.
// It validates the URL by sending a GET request with a 3-second timeout,
// then saves the configuration and returns a JSON result.
func ConfigureWebhook(ctx *fiber.Ctx) error {
	// Parse request body.
	type requestBody struct {
		WebhookURL string `json:"webhook_url"`
	}
	var req requestBody
	if err := ctx.BodyParser(&req); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"error": "Invalid request body",
		})
	}

	if req.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"error": "webhook_url is required",
		})
	}

	// Validate the URL by sending a test GET request with a 3-second timeout.
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	resp, err := client.Get(req.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadGateway).JSON(fiber.Map{
			"error": "Failed to reach webhook URL: " + err.Error(),
		})
	}
	resp.Body.Close()

	// Consider a non-2xx status code as a failure.
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return ctx.Status(fiber.StatusBadGateway).JSON(fiber.Map{
			"error": "Webhook URL returned status code " + http.StatusText(resp.StatusCode),
		})
	}

	// Save the configuration (store it in memory, thread‑safe).
	mu.Lock()
	webhookConfig.WebhookURL = req.WebhookURL
	mu.Unlock()

	// Return success.
	return ctx.JSON(fiber.Map{
		"status":  "success",
		"message": "Webhook configured successfully",
		"webhook_url": req.WebhookURL,
	})
}

func main() {
	app := fiber.New()

	// Register the route.
	app.Post("/configure-webhook", ConfigureWebhook)

	// Start the server.
	log.Println("Server starting on :3000")
	if err := app.Listen(":3000"); err != nil {
		log.Fatal(err)
	}
}

