package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"time"

	"github.com/gofiber/fiber/v2"
)

var webhookConfig struct {
	URL string `json:"webhook_url"`
}

func main() {
	app := fiber.New()

	app.Post("/configure-webhook", ConfigureWebhook)

	log.Fatal(app.Listen(":3000"))
}

func ConfigureWebhook(ctx *fiber.Ctx) error {
	var reqBody struct {
		WebhookURL string `json:"webhook_url"`
	}

	if err := ctx.BodyParser(&reqBody); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid request body",
		})
	}

	if reqBody.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook_url is required",
		})
	}

	client := http.Client{
		Timeout: 3 * time.Second,
	}

	resp, err := client.Get(reqBody.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusOK).JSON(fiber.Map{
			"success": false,
			"error":   fmt.Sprintf("Failed to reach webhook: %v", err),
		})
	}
	defer resp.Body.Close()

	webhookConfig.URL = reqBody.WebhookURL

	return ctx.Status(fiber.StatusOK).JSON(fiber.Map{
		"success":     true,
		"message":     "Webhook configured and validated",
		"webhook_url": reqBody.WebhookURL,
	})
}

