// ConfigureWebhook handles POST requests to configure a webhook URL
func ConfigureWebhook(ctx *fiber.Ctx) error {
	// Parse the JSON request body
	var req webhookRequest
	if err := ctx.BodyParser(&req); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid JSON format",
		})
	}

	// Validate that webhook_url is provided
	if req.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook_url is required",
		})
	}

	// Validate URL format
	parsedURL, err := url.ParseRequestURI(req.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid webhook URL format",
		})
	}

	// Ensure the URL has a valid scheme
	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook URL must use http or https scheme",
		})
	}

	// SSRF prevention: block requests to private/internal IP addresses
	if isPrivateAddress(parsedURL.Host) {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook URL targets an internal or private address, which is not allowed",
		})
	}

	// Create a custom HTTP client with timeout and disabled redirects
	client := &http.Client{
		Timeout: 3 * time.Second,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			// Do not follow any redirects to prevent SSRF via redirect
			return errors.New("redirects are not allowed")
		},
	}

	// Send a test GET request to the webhook URL
	resp, err := client.Get(req.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Failed to send test request to webhook URL",
		})
	}
	defer resp.Body.Close()

	// Check if the webhook responded successfully (2xx status)
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   fmt.Sprintf("Webhook URL returned non-success status: %d", resp.StatusCode),
		})
	}

	// Save the configuration (placeholder for actual database operation)
	// db.SaveWebhookURL(req.WebhookURL)

	// Return success response
	return ctx.Status(fiber.StatusOK).JSON(fiber.Map{
		"success": true,
		"message": "Webhook configured successfully",
	})
}

// isPrivateAddress checks whether the given host (with optional port) resolves to a private,
// loopback, link-local, or unspecified IP address.
func isPrivateAddress(host string) bool {
	// Split host and port (if present)
	hostname, _, err := net.SplitHostPort(host)
	if err != nil {
		// No port or malformed; treat the whole string as hostname
		hostname = host
	}

	// Try to parse as an IP address directly
	ip := net.ParseIP(hostname)
	if ip != nil {
		return isRestrictedIP(ip)
	}

	// It's a hostname, resolve it and check all returned IPs
	ips, err := net.LookupIP(hostname)
	if err != nil {
		// If resolution fails, consider it unsafe to allow
		return true
	}
	for _, ip := range ips {
		if isRestrictedIP(ip) {
			return true
		}
	}
	return false
}

// isRestrictedIP returns true if the IP falls into a category that should be blocked
// for outgoing requests (loopback, private, link-local, unspecified).
func isRestrictedIP(ip net.IP) bool {
	return ip.IsLoopback() ||
		ip.IsPrivate() ||
		ip.IsLinkLocalUnicast() ||
		ip.IsLinkLocalMulticast() ||
		ip.IsUnspecified()
}

