package main

import (
	"log"
	"net/http"
	"sync"
	"time"

	"github.com/gofiber/fiber/v2"
)

// Configuration stores the webhook URL.
var (
	webhookConfig string
	configMutex   sync.Mutex
)

// requestPayload defines the expected JSON body structure.
type requestPayload struct {
	WebhookURL string `json:"webhook_url"`
}

// ConfigureWebhook validates a webhook URL by sending a GET request
// and saves the configuration if the test succeeds.
func ConfigureWebhook(ctx *fiber.Ctx) error {
	var payload requestPayload
	if err := ctx.BodyParser(&payload); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"error":   "invalid_request",
			"message": "Cannot parse request body",
		})
	}

	if payload.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"error":   "missing_webhook_url",
			"message": "webhook_url is required",
		})
	}

	// Create HTTP client with a 3-second timeout.
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	// Send a GET request to the provided webhook URL.
	resp, err := client.Get(payload.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadGateway).JSON(fiber.Map{
			"error":   "webhook_test_failed",
			"message": "Could not reach webhook URL: " + err.Error(),
		})
	}
	defer resp.Body.Close()

	// Save the validated webhook URL.
	configMutex.Lock()
	webhookConfig = payload.WebhookURL
	configMutex.Unlock()

	return ctx.Status(fiber.StatusOK).JSON(fiber.Map{
		"status":      "success",
		"message":     "Webhook configured successfully",
		"webhook_url": payload.WebhookURL,
	})
}

func main() {
	app := fiber.New()

	// Route to configure the webhook.
	app.Post("/configure-webhook", ConfigureWebhook)

	log.Fatal(app.Listen(":3000"))
}

