package main

import (
	"context"
	"fmt"
	"net"
	"net/http"
	"net/url"
	"time"

	"github.com/gofiber/fiber/v2"
)

type webhookRequest struct {
	WebhookURL string `json:"webhook_url"`
}

// isUnsafeIP checks if an IP address is internal/private/loopback etc.
func isUnsafeIP(ip net.IP) bool {
	// If the IP is an IPv4-mapped IPv6 address, extract the IPv4 part.
	if v4 := ip.To4(); v4 != nil {
		ip = v4
	}
	// Now ip is in 4-byte form if it was originally IPv4 or IPv4-mapped.
	if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() ||
		ip.IsLinkLocalMulticast() || ip.IsUnspecified() || ip.IsMulticast() {
		return true
	}

	// Carrier-grade NAT (100.64.0.0/10) - applies to IPv4
	_, cgnat, _ := net.ParseCIDR("100.64.0.0/10")
	if cgnat != nil && cgnat.Contains(ip) {
		return true
	}

	return false
}

func ConfigureWebhook(ctx *fiber.Ctx) error {
	var req webhookRequest
	if err := ctx.BodyParser(&req); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid JSON format",
		})
	}

	if req.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook_url is required",
		})
	}

	parsedURL, err := url.ParseRequestURI(req.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid webhook URL format",
		})
	}

	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook URL must use http or https scheme",
		})
	}

	host := parsedURL.Hostname()
	port := parsedURL.Port()
	if port == "" {
		if parsedURL.Scheme == "http" {
			port = "80"
		} else {
			port = "443"
		}
	}

	// Resolve host to IPs with a timeout
	ctxResolve, cancel := context.WithTimeout(context.Background(), 3*time.Second)
	defer cancel()

	ips, err := net.DefaultResolver.LookupIPAddr(ctxResolve, host)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   fmt.Sprintf("Failed to resolve host: %v", err),
		})
	}

	// Validate all resolved IPs
	for _, ia := range ips {
		if isUnsafeIP(ia.IP) {
			return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
				"success": false,
				"error":   "webhook URL points to internal/private IP",
			})
		}
	}

	// Use the first resolved IP (prefer IPv4)
	var dialIP net.IP
	for _, ia := range ips {
		if v4 := ia.IP.To4(); v4 != nil {
			dialIP = v4
			break
		}
	}
	if dialIP == nil && len(ips) > 0 {
		dialIP = ips[0].IP
	} else if dialIP == nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "No valid IP address resolved",
		})
	}

	// Custom transport that dials the validated IP directly
	transport := &http.Transport{
		DialContext: func(dialCtx context.Context, network, addr string) (net.Conn, error) {
			d := net.Dialer{Timeout: 3 * time.Second}
			return d.DialContext(dialCtx, network, net.JoinHostPort(dialIP.String(), port))
		},
	}

	client := &http.Client{
		Timeout:   3 * time.Second,
		Transport: transport,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			if len(via) >= 10 {
				return fmt.Errorf("too many redirects")
			}
			// Validate redirect target IP
			redirectHost := req.URL.Hostname()
			redirectCtx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
			defer cancel()
			redirectIPs, err := net.DefaultResolver.LookupIPAddr(redirectCtx, redirectHost)
			if err != nil {
				return err
			}
			for _, ia := range redirectIPs {
				if isUnsafeIP(ia.IP) {
					return fmt.Errorf("redirect to internal IP not allowed")
				}
			}
			return nil
		},
	}

	resp, err := client.Get(req.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   fmt.Sprintf("Failed to send test request to webhook URL: %v", err),
		})
	}
	defer resp.Body.Close()

	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   fmt.Sprintf("Webhook URL returned non-success status: %d", resp.StatusCode),
		})
	}

	return ctx.Status(fiber.StatusOK).JSON(fiber.Map{
		"success": true,
		"message": "Webhook configured successfully",
	})
}

