var savedWebhookURL string // stores the configured webhook URL

func main() {
    app := fiber.New()

    app.Post("/configure-webhook", ConfigureWebhook)

    if err := app.Listen(":3000"); err != nil {
        panic(err)
    }
}

// ConfigureWebhook handles POST requests with a JSON body containing a "webhook_url" field.
// It validates the URL by sending a test GET request with a 3-second timeout, saves the
// configuration, and returns a JSON response indicating the result.
func ConfigureWebhook(ctx *fiber.Ctx) error {
    type request struct {
        WebhookURL string `json:"webhook_url"`
    }

    var req request
    if err := ctx.BodyParser(&req); err != nil {
        return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
            "error": "Invalid request body",
        })
    }

    if req.WebhookURL == "" {
        return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
            "error": "webhook_url is required",
        })
    }

    // Validate the webhook URL by sending a GET request with a 3-second timeout.
    client := &http.Client{
        Timeout: 3 * time.Second,
    }

    resp, err := client.Get(req.WebhookURL)
    if err != nil {
        return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
            "error": "Failed to reach webhook URL: " + err.Error(),
        })
    }
    defer resp.Body.Close()

    if resp.StatusCode >= 400 {
        return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
            "error": "Webhook URL returned non-successful status code",
        })
    }

    // Save the configuration (here we store it in a global variable).
    savedWebhookURL = req.WebhookURL

    return ctx.JSON(fiber.Map{
        "status":      "success",
        "message":     "Webhook configured successfully",
        "webhook_url": savedWebhookURL,
    })
}

