package main

import (
	"context"
	"crypto/tls"
	"errors"
	"fmt"
	"net"
	"net/http"
	"net/url"
	"time"

	"github.com/gofiber/fiber/v2"
)

// webhookRequest represents the expected JSON request body
type webhookRequest struct {
	WebhookURL string `json:"webhook_url"`
}

// ConfigureWebhook handles POST requests to configure a webhook URL.
// It validates the URL, performs a GET test request (with SSRF protection),
// and returns the result as JSON.
func ConfigureWebhook(ctx *fiber.Ctx) error {
	// Parse JSON body
	var req webhookRequest
	if err := ctx.BodyParser(&req); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid JSON format",
		})
	}

	if req.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook_url is required",
		})
	}

	// Basic URL validation
	parsedURL, err := url.ParseRequestURI(req.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid webhook URL format",
		})
	}

	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook URL must use http or https scheme",
		})
	}

	// Extract hostname for SSRF checks and TLS SNI
	host := parsedURL.Hostname()
	if host == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid webhook URL: missing host",
		})
	}

	// Build an HTTP client that prevents SSRF by:
	// 1. Resolving the hostname and blocking private/internal IPs
	// 2. Disabling automatic redirects
	transport := &http.Transport{
		DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
			return ssrfDialContext(ctx, network, addr)
		},
		// For HTTPS, force the TLS SNI to the original hostname
		TLSClientConfig: &tls.Config{
			ServerName: host,
		},
	}

	client := &http.Client{
		Timeout:   3 * time.Second,
		Transport: transport,
		// Do not follow redirects – a redirect could bypass IP checks
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			return http.ErrUseLastResponse
		},
	}

	// Perform a GET request as required
	resp, err := client.Get(req.WebhookURL)
	if err != nil {
		// Do not leak internal error details
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Webhook URL is not reachable",
		})
	}
	defer resp.Body.Close()

	// Only 2xx status codes are considered successful
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Webhook URL did not respond with a success status",
		})
	}

	// Placeholder for persisting the webhook URL
	// db.SaveWebhookURL(req.WebhookURL)

	return ctx.Status(fiber.StatusOK).JSON(fiber.Map{
		"success": true,
		"message": "Webhook configured successfully",
	})
}

// isPublicIP returns true if the given IP is safe to connect to (i.e., not loopback,
// private, link-local, unspecified, or multicast).
func isPublicIP(ip net.IP) bool {
	if ip == nil {
		return false
	}
	// Use standard library checks to block reserved/private ranges
	if ip.IsLoopback() ||
		ip.IsPrivate() ||
		ip.IsLinkLocalUnicast() ||
		ip.IsLinkLocalMulticast() ||
		ip.IsUnspecified() ||
		ip.IsMulticast() ||
		ip.IsInterfaceLocalMulticast() {
		return false
	}
	return true
}

// ssrfDialContext is a custom dial function that resolves the hostname and only
// allows connections to public IP addresses.
func ssrfDialContext(ctx context.Context, network, addr string) (net.Conn, error) {
	host, port, err := net.SplitHostPort(addr)
	if err != nil {
		return nil, err
	}

	// Resolve host to IP addresses using the default resolver
	ips, err := net.DefaultResolver.LookupIPAddr(ctx, host)
	if err != nil {
		return nil, err
	}

	// Select the first public IP
	var allowedIP net.IP
	for _, ipAddr := range ips {
		if isPublicIP(ipAddr.IP) {
			allowedIP = ipAddr.IP
			break
		}
	}

	if allowedIP == nil {
		return nil, errors.New("connection to internal or non-public IP is not allowed")
	}

	// Dial the TCP connection to the allowed IP and port
	dialer := net.Dialer{}
	return dialer.DialContext(ctx, network, net.JoinHostPort(allowedIP.String(), port))
}

func main() {
	app := fiber.New()
	app.Post("/configure-webhook", ConfigureWebhook)
	fmt.Println("Server starting on :3000")
	if err := app.Listen(":3000"); err != nil {
		panic(err)
	}
}

