package main

import (
    "net/http"
    "time"

    "github.com/gofiber/fiber/v2"
)

var configuredWebhookURL string

func main() {
    app := fiber.New()
    app.Post("/configure-webhook", ConfigureWebhook)
    app.Listen(":3000")
}

type configureRequest struct {
    WebhookURL string `json:"webhook_url"`
}

func ConfigureWebhook(ctx *fiber.Ctx) error {
    var req configureRequest
    if err := ctx.BodyParser(&req); err != nil {
        return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{"error": "Invalid request body"})
    }
    if req.WebhookURL == "" {
        return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{"error": "webhook_url is required"})
    }

    client := http.Client{Timeout: 3 * time.Second}
    resp, err := client.Get(req.WebhookURL)
    if err != nil {
        return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{"error": "Failed to reach webhook URL: " + err.Error()})
    }
    defer resp.Body.Close()
    if resp.StatusCode != http.StatusOK {
        return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{"error": "Webhook URL returned non-200 status: " + resp.Status})
    }

    configuredWebhookURL = req.WebhookURL

    return ctx.JSON(fiber.Map{
        "status":  "success",
        "message": "Webhook configured successfully",
    })
}

