// baseDialer is a standard dialer with sensible timeouts
var baseDialer = &net.Dialer{
	Timeout:   3 * time.Second,
	KeepAlive: 3 * time.Second,
}

// ssrfSafeTransport is a custom HTTP transport that prevents connections to
// internal, private, loopback, link-local and other non-global unicast addresses.
var ssrfSafeTransport = &http.Transport{
	DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
		host, port, err := net.SplitHostPort(addr)
		if err != nil {
			return nil, err
		}

		// Resolve hostname to IP addresses
		ips, err := net.DefaultResolver.LookupIPAddr(ctx, host)
		if err != nil {
			return nil, err
		}

		// Find the first public (global unicast) IP address
		var resolvedIP net.IP
		for _, ia := range ips {
			ip := ia.IP
			if ip.IsGlobalUnicast() {
				resolvedIP = ip
				break
			}
		}

		if resolvedIP == nil {
			return nil, fmt.Errorf("all resolved IP addresses for %s are restricted", host)
		}

		// Dial the selected public IP
		return baseDialer.DialContext(ctx, network, net.JoinHostPort(resolvedIP.String(), port))
	},
	MaxIdleConns:          10,
	IdleConnTimeout:       30 * time.Second,
	DisableCompression:    true,
	ResponseHeaderTimeout: 3 * time.Second,
}

// safeHTTPClient is an HTTP client that uses SSRF-safe transport, disables redirects,
// and enforces an overall request timeout.
var safeHTTPClient = &http.Client{
	Transport: ssrfSafeTransport,
	Timeout:   3 * time.Second,
	CheckRedirect: func(req *http.Request, via []*http.Request) error {
		// Do not follow redirects to prevent redirect-based SSRF
		return http.ErrUseLastResponse
	},
}

// ConfigureWebhook handles POST requests to configure a webhook URL.
// It validates the JSON body, checks URL format, performs a GET test request
// using an SSRF-safe client, and returns the result.
func ConfigureWebhook(ctx *fiber.Ctx) error {
	// Parse the JSON request body
	var req webhookRequest
	if err := ctx.BodyParser(&req); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid JSON format",
		})
	}

	// Validate that webhook_url is provided
	if req.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook_url is required",
		})
	}

	// Validate URL format
	parsedURL, err := url.ParseRequestURI(req.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid webhook URL format",
		})
	}

	// Ensure the URL has a valid scheme
	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook URL must use http or https scheme",
		})
	}

	// Create a GET request with the fiber request context (for automatic cancellation)
	httpReq, err := http.NewRequestWithContext(ctx.Context(), "GET", req.WebhookURL, nil)
	if err != nil {
		return ctx.Status(fiber.StatusInternalServerError).JSON(fiber.Map{
			"success": false,
			"error":   "Failed to create test request",
		})
	}

