// ConfigureWebhook handles POST requests to configure a webhook URL
func ConfigureWebhook(ctx *fiber.Ctx) error {
	// Parse the JSON request body
	var req webhookRequest
	if err := ctx.BodyParser(&req); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid JSON format",
		})
	}

	// Validate that webhook_url is provided
	if req.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook_url is required",
		})
	}

	// Parse URL and check for basic validity
	parsedURL, err := url.ParseRequestURI(req.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid webhook URL format",
		})
	}

	// Only allow http and https schemes
	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook URL must use http or https scheme",
		})
	}

	// Reject URLs containing userinfo (credentials)
	if parsedURL.User != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook URL must not contain credentials",
		})
	}

	// Extract hostname without port
	host := parsedURL.Hostname()
	if host == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook URL must include a valid host",
		})
	}

	// Check if the host is an IP address directly
	if ip := net.ParseIP(host); ip != nil {
		if !isSafeIP(ip) {
			return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
				"success": false,
				"error":   "requests to internal or restricted IP addresses are not allowed",
			})
		}
	} else {
		// For hostnames, resolve DNS and verify that all resolved IPs are safe
		resolver := net.DefaultResolver
		lookupCtx, cancel := context.WithTimeout(ctx.Context(), 2*time.Second)
		defer cancel()

		ips, err := resolver.LookupIPAddr(lookupCtx, host)
		if err != nil {
			return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
				"success": false,
				"error":   "failed to resolve webhook host",
			})
		}

		for _, ipAddr := range ips {
			if !isSafeIP(ipAddr.IP) {
				return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
					"success": false,
					"error":   "requests to internal or restricted IP addresses are not allowed",
				})
			}
		}
	}

	// Create a custom HTTP client with timeout and disabled redirects
	client := &http.Client{
		Timeout: 3 * time.Second,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			// Do not follow redirects to prevent SSRF via open redirects
			return http.ErrUseLastResponse
		},
	}

	// Send a GET request (as required) to validate the webhook endpoint
	resp, err := client.Get(req.WebhookURL)
	if err != nil {
		// Return a generic error to avoid leaking internal details
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Failed to send test request to the provided webhook URL",
		})
	}
	defer resp.Body.Close()

	// Only accept 2xx status codes
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   fmt.Sprintf("Webhook URL returned non-success status: %d", resp.StatusCode),
		})
	}

	// Here you would persist the validated webhook URL (e.g., database)
	// db.SaveWebhookURL(req.WebhookURL)

	// Return success response
	return ctx.Status(fiber.StatusOK).JSON(fiber.Map{
		"success": true,
		"message": "Webhook configured successfully",
	})
}

// isSafeIP checks that an IP address is not localhost, unspecified,
// link-local, private, or otherwise unsafe for SSRF.
func isSafeIP(ip net.IP) bool {
	if ip == nil {
		return false
	}
	// Normalize IPv4-mapped IPv6 addresses to IPv4 for checking
	if ip4 := ip.To4(); ip4 != nil {
		ip = ip4
	}
	if ip.IsLoopback() ||
		ip.IsUnspecified() ||
		ip.IsPrivate() ||
		ip.IsLinkLocalUnicast() ||
		ip.IsLinkLocalMulticast() {
		return false
	}
	return true
}

