package main

import (
	"fmt"
	"net/http"
	"time"

	"github.com/gofiber/fiber/v2"
)

// In-memory storage for webhook configurations.
// In a real application this would be a database or persistent store.
var webhookConfigs = make(map[string]bool)

// ConfigureWebhook validates and saves a webhook URL.
func ConfigureWebhook(ctx *fiber.Ctx) error {
	// Define the expected request body.
	type request struct {
		WebhookURL string `json:"webhook_url"`
	}

	var req request
	if err := ctx.BodyParser(&req); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"error": "Invalid request body",
		})
	}

	if req.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"error": "webhook_url is required",
		})
	}

	// Validate the webhook URL by sending a test GET request.
	client := &http.Client{
		Timeout: 3 * time.Second, // Required 3‑second timeout.
	}

	resp, err := client.Get(req.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusInternalServerError).JSON(fiber.Map{
			"error": "Failed to connect to webhook URL: " + err.Error(),
		})
	}
	defer resp.Body.Close()

	// Only accept 2xx status codes as successful validation.
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"error": fmt.Sprintf("Webhook URL returned status %d", resp.StatusCode),
		})
	}

	// Save the configuration.
	webhookConfigs[req.WebhookURL] = true

	return ctx.JSON(fiber.Map{
		"status":  "success",
		"message": "Webhook configured successfully",
	})
}

func main() {
	app := fiber.New()

	// Register the webhook configuration endpoint.
	app.Post("/configure-webhook", ConfigureWebhook)

	// Start the server on port 3000.
	if err := app.Listen(":3000"); err != nil {
		panic(err)
	}
}

